import{_ as t,o,c as a,a3 as n}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"Image model deploy","description":"Run A1111 or ComfyUI on your PC for MiniTavern LAN image gen — local Stable Diffusion when you have no cloud image API.","frontmatter":{"title":"Image model deploy","description":"Run A1111 or ComfyUI on your PC for MiniTavern LAN image gen — local Stable Diffusion when you have no cloud image API.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Image model deploy · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Run A1111 or ComfyUI on your PC for MiniTavern LAN image gen — local Stable Diffusion when you have no cloud image API."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local/image-gen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local/image-gen"}]]},"headers":[],"relativePath":"en/local/image-gen/index.md","filePath":"en/local/image-gen/index.md","lastUpdated":1787224147000}'),r={name:"en/local/image-gen/index.md"};function i(d,e,l,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="image-model-deploy" tabindex="-1">Image model deploy <a class="header-anchor" href="#image-model-deploy" aria-label="Permalink to &quot;Image model deploy&quot;">​</a></h1><p>MiniTavern supports cloud image gen (OpenAI / Gemini / OpenRouter / Qwen) and <strong>local</strong> Stable Diffusion–family services:</p><table tabindex="0"><thead><tr><th>Local backend</th><th>App platform</th><th>Default port</th></tr></thead><tbody><tr><td><a href="./a1111">AUTOMATIC1111 / SD WebUI</a></td><td>A1111(SD WebUI)</td><td><code>7860</code></td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>ComfyUI</td><td><code>8188</code> (Desktop often <code>8000</code>)</td></tr></tbody></table><p>MiniTavern on the phone <strong>does not run</strong> diffusion models on the device; images are generated on the PC (or cloud GPU). The App only sends requests and shows results.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Suggestion</th></tr></thead><tbody><tr><td>PC</td><td>Windows is easiest; macOS / Linux also fine</td></tr><tr><td>GPU</td><td><strong>NVIDIA 6GB+</strong> is comfortable (SD 1.5); SDXL / larger models prefer <strong>8–12GB+</strong></td></tr><tr><td>No discrete GPU</td><td>Try CPU (very slow) or rent a cloud GPU (hourly, not free)</td></tr><tr><td>Network</td><td>Phone and PC on the same Wi‑Fi (avoid guest isolation)</td></tr><tr><td>Disk</td><td>Models often <strong>2–10GB+</strong> each — leave space</td></tr></tbody></table><p>No GPU and no desire to deploy: use free cloud image tiers in <a href="/ultra_guides/en/free-cloud/#free-image-generation">Free cloud · Image gen</a> if available, or chat only for now.</p><h2 id="which-path" tabindex="-1">Which path <a class="header-anchor" href="#which-path" aria-label="Permalink to &quot;Which path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Best for</th><th>Difficulty</th></tr></thead><tbody><tr><td><a href="./a1111">A1111</a></td><td>Classic WebUI, clear parameters, common with tavern ecosystems</td><td>Medium</td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>Workflows / fast new-model support; App uses a built-in default workflow</td><td>Medium</td></tr></tbody></table><p>Both end at: <a href="./connect-app">Configure image gen in MiniTavern</a>.</p><h2 id="suggested-reading-order" tabindex="-1">Suggested reading order <a class="header-anchor" href="#suggested-reading-order" aria-label="Permalink to &quot;Suggested reading order&quot;">​</a></h2><ol><li>Pick <a href="./a1111">A1111</a> or <a href="./comfyui">ComfyUI</a> by hardware; install and download models</li><li>Enable <strong>API + LAN listen</strong> (each guide explains)</li><li><a href="./connect-app">Connect MiniTavern</a> and Test</li><li>In chat use <code>/imagine</code> or Attach → Image gen (see <a href="/ultra_guides/en/manual/model-link#image-gen-link--reply-images--keywords">Model link · Image gen</a>)</li><li>Back to <a href="/ultra_guides/en/local/">Run local models</a> overview</li></ol><h2 id="important-reminders" tabindex="-1">Important reminders <a class="header-anchor" href="#important-reminders" aria-label="Permalink to &quot;Important reminders&quot;">​</a></h2><ul><li>On the phone use the PC’s <strong>LAN IP</strong> (e.g. <code>192.168.1.8</code>) — <strong>not</strong> <code>localhost</code> / <code>127.0.0.1</code>.</li><li>A1111 needs <strong><code>--api</code></strong>; opening the Web UI alone is not enough.</li><li>ComfyUI needs <strong><code>--listen</code></strong> (or Desktop Listen <code>0.0.0.0</code>) for phone access.</li><li>Allow ports in the firewall; do not expose an unauthenticated image API to the public internet.</li><li>The App’s default Comfy workflow <strong>does not consume reference images</strong>; for face lock prefer A1111 or a cloud platform that supports refs.</li></ul>',14)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
